#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int main(int argc, char **argv) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    char *end;
    // Parse base
    long long base = strtoll(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Parse exponent
    long long exp = strtoll(argv[2], &end, 10);
    if (end == argv[2] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Parse modulus
    long long mod = strtoll(argv[3], &end, 10);
    if (end == argv[3] || *end != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (mod <= 0) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    // Reduce base modulo mod, handling negative base
    long long b = base % mod;
    if (b < 0) b += mod;

    long long result = 1 % mod; // ensures result is within [0, mod-1]
    long long e = exp;
    while (e > 0) {
        if (e & 1LL) {
            __uint128_t mul = ( (__uint128_t) result * (unsigned long long) b );
            result = (long long)(mul % (unsigned long long) mod);
        }
        e >>= 1LL;
        if (e) { // avoid unnecessary square on last iteration
            __uint128_t sq = ( (__uint128_t) b * (unsigned long long) b );
            b = (long long)(sq % (unsigned long long) mod);
        }
    }

    printf("result=%lld\n", result);
    return 0;
}
